/// word or value, 3 not reachable or a call of a watch could not be read. `wait` is what the program does while a
/// watch runs (until the user stops it) and says why it ended: `Ok` if the user stopped it, an error if the connection
/// was lost (`Disconnected` is 3); the code is made after it, from that and from what the listeners counted.
pub async fn run_to_exit<W, F>(root: &crate::common_capnp::change_listener::Client, words: &[&str], inp: &mut dyn Input, out: &mut dyn Output, wait: W) -> i32 where W: FnOnce() -> F, F: ::core::future::Future<Output = Result<(), CallError>> {
    let result = match dispatch(words) {
        Some(go) => go(root, inp, out).await,
        None => Err(CallError::at("", ErrorKind::BadValue(format!("no command `{}`", words.join(" "))))),
    };
    let result = match result {
        Ok(o) if o.is_watching() => wait().await.map(|()| o),
        other => other,
    };
    capnp_compiler::cligen::rt::exit_code(&result)
}

/// `common/ChangeListener.change`
pub async fn run_change_listener_change(root: &crate::common_capnp::change_listener::Client, inp: &mut dyn Input, out: &mut dyn Output) -> Result<Outcome, CallError> {
    let mut req = root.change_request();
    set_common_capnp_change_listener_change_params(req.get(), inp, "")?;
    req.send().await?;
    let _ = out;
    Ok(Outcome::none())
}

/// `common/ChangeListener.ended`
pub async fn run_change_listener_ended(root: &crate::common_capnp::change_listener::Client, inp: &mut dyn Input, out: &mut dyn Output) -> Result<Outcome, CallError> {
    let mut req = root.ended_request();
    set_common_capnp_change_listener_ended_params(req.get(), inp, "")?;
    let resp = req.send().promise.await?;
    out_common_capnp_change_listener_ended_results(resp.get()?, "", out)?;
    Ok(Outcome::none())
}

#[allow(unused_variables, unused_mut)]
fn set_common_capnp_change(mut b: crate::common_capnp::change::Builder<'_>, inp: &mut dyn Input, path: &str) -> Result<(), CallError> {
    if [inp.has(&join(path, "created")), inp.has(&join(path, "updated")), inp.has(&join(path, "deleted"))].iter().filter(|x| **x).count() > 1 { return Err(CallError::union_twice(path)); }
    let p = join(path, "created");
    if inp.has(&p) { set_common_capnp_envelope(b.reborrow().init_created(), inp, &p)?; }
    let p = join(path, "updated");
    if inp.has(&p) { set_common_capnp_envelope(b.reborrow().init_updated(), inp, &p)?; }
    let p = join(path, "deleted");
    if inp.has(&p) { set_common_capnp_uuid(b.reborrow().init_deleted(), inp, &p)?; }
    Ok(())
}

