fn set_common_capnp_problem(mut b: crate::common_capnp::problem::Builder<'_>, inp: &mut dyn Input, path: &str) -> Result<(), CallError> {
    let p = join(path, "type");
    if let Some(v) = inp.text(&p)? {
        b.set_type(v.as_str());
    }
    let p = join(path, "title");
    if let Some(v) = inp.text(&p)? {
        b.set_title(v.as_str());
    }
    let p = join(path, "detail");
    if let Some(v) = inp.text(&p)? {
        b.set_detail(v.as_str());
    }
    let p = join(path, "status");
    if let Some(v) = inp.int(&p)? {
        b.set_status(u16::try_from(v).map_err(|_| CallError::out_of_range(&p, "u16"))?);
    }
    let p = join(path, "extensions");
    if let Some(n) = inp.count(&p)? {
        let mut l = b.reborrow().init_extensions(n);
        for i0 in 0..n {
            let e0 = join(&p, &i0.to_string());
            set_common_capnp_extension(l.reborrow().get(i0), inp, &e0)?;
        }
    }
    Ok(())
}

